Our problem of interest is the following Empirical Risk Minimization (ERM) problem (also called the \textit{finite-sum} problem) with constraints: 
\begin{equation}\label{pro: ERM}
	\text{ERM:} \ \ \ \ \    \text{minimize}_{x \in \calC} \quad F(x):= \tfrac{1}{n} \sum_{i=1}^{n} f_i(x) \ , 
\end{equation}
where $f_i(\cdot): \mathbb{R}^p \to \mathbb{R}$ is the loss function of observation $i$ for $i=1,\dots, n$, and $x$ is comprised of the (model) coefficients/parameters which are to be optimized over the feasibility set $\calC \subset \mathbb{R}^p$. Problem \cref{pro: ERM} is a fundamental problem in statistical and machine learning, as it is the underlying optimization problem on which models are ``trained'' or ``learned'', see  \cite{vapnik1991principles,hastie2009elements}. The number of observations $n$ can be significantly larger than the dimension $p$, and our interest here will be in the regime where $n \gg p$.
We make the following assumptions for $\erm$ problems throughout this paper:
\begin{assumption}\label{assump: ERM}
	The following conditions hold for the $\erm$ problem \cref{pro: ERM}:
	\begin{enumerate}
		\item[(i)] the feasibility set $\mathcal{C}$ is a compact convex set,
		\item[(ii)] for any $g \in \mathbb{R}^p$, the linear minimization problem $\arg\min_{x\in\calC} g^\top x$
		can be easily solved, 
		\item[(iii)] for all $i\in[n]$, the multivariate loss function $f_i(\cdot)$ is twice-differentiable and its gradient $\nabla f_i(\cdot)$ is $L$-Lipschitz continuous on $\calC$, namely, 
		\begin{equation}\label{eq: ERM ass lip 1}
			\| \nabla f_i(u) - \nabla f_i(v) \|_* \le L \|u-v\| ~~\text{ for any $u,v\in \calC$}
		\end{equation}
		where $\|\cdot\|_*$ is the dual norm of the norm on the space of variables, and 
		\item[(iv)] for all $i\in[n]$, the Hessian $\nabla^2 f_i(\cdot)$ is $\hat{L}$-Lipschitz continuous on $\calC$, namely
		\begin{equation}\label{eq: ERM ass lip 2}
			\| \nabla^2 f_i(u) - \nabla^2 f_i(v) \| \le \hat{L} \|u-v\|~~\text{ for any $u,v\in \calC$}
		\end{equation}
		where the norm of the Hessian matrices is the operator norm induced by the norm on the space of variables.
	\end{enumerate}
\end{assumption}


\subsection{Notation}

Let $\mathbb{N}$ denote the natural numbers.  For any $n \in \mathbb{N}$, we use $[n]$ to denote the set $\{1,2,\dots,n\}$.
For any real number $v$, we use $\lfloor v \rfloor$ to denote the largest integer number less than or equal to $v$.
Depending on the context, we will use either $\langle a,b\rangle$ or $a^\top b$ to denote the inner product between $a$ and $b$ in Euclidean space. For a vector $x$ in $\mathbb{R}^p$, the norm $\|x\|_q$ is given by $(\sum_{j=1}^{p}x_j^q)^{1/q}$ for $q \in [1,\infty)$ and $\|x\|_\infty := \max_{j} |x_j|$. The dual of norm $\|\cdot\|$ is defined as $\|z\|_* := \sup\{z^\top x : \|x\| \le 1\}$.  For a matrix $A \in \mathbb{R}^{p \times p}$, the matrix operator norm $\|A\|$ induced by the norm $\|\cdot\|$ is defined as $\sup_{x: \|x\| \le 1} \|Ax\|_*$. For any symmetric positive definite matrix $A\in \mathbb{S}^{p\times p}$, we define its induced norm on $\mathbb{R}^p$ by $\|z\|_A := \sqrt{z^\top A z}$.  We define $\sum_{i=j}^k \alpha_i := 0$ whenever $j > k$.  We denote the uniform distribution on the set $S$ by $\calU(S)$, and we denote the Bernoulli distribution with probability $p$ by $\mathrm{Ber}(p)$.


In this section we present a new type of Frank-Wolfe algorithm whose newness derives from the way in which approximate gradients are computed.  We call the algorithm TUFW for ``Taylor-point Updating Frank-Wolfe''. Algorithm TUFW is similar to the standard Frank-Wolfe method except that it computes an inexpensive estimate $g^k$ of the gradient $\nabla F(x^k)$ at iteration $k$.  And it differs from other Frank-Wolfe methods in the way it computes the estimate $g^k$ in that (i) TUFW explicitly uses second-derivative (Hessian) information of the loss functions $f_i$, and (ii) it can use very different batch-size rules -- both stochastic and deterministic. TUFW is described in \cref{alg: TUFW in general finite sum}.  We now explain the steps of the method.


\begin{algorithm}
	\caption{(TUFW) Frank-Wolfe Method with Taylor Point Updating}
	\label{alg: TUFW in general finite sum}
	\begin{algorithmic}[1]
		\STATE \textbf{input}  initial point $x^0$, step-size sequence $\{\gamma_k\}_k$, and (possibly) number of iterations $K$
		\STATE \textbf{initialize Taylor points} $\calB_0 \gets [n]$ and $b_i \leftarrow x^0$ for $i\in [n]$  \; \label{bettina}
		\FOR{$k=0,1,2,\dots,K$,}
		\STATE\label{algline: 3}\textbf{If $k>0$, update Taylor points}: \\ \ \ Use some \textbf{Rule} to construct set $\calB_k \subset [n]$ of indices for Taylor-point updating\\ \ \ Update Taylor points:  for $i\in\calB_k$ update $b_i \gets x^k$ \; \label{fanette}
		\STATE\label{algline: 4}  \textbf{Compute estimates of individual gradients}:\\ $g^k_{i}\gets \nabla f_{i}(b_{i})  +  \nabla^2 f_i (b_{i}) ( x^k -  b_{i} ) $ for $i\in [n]$\; \label{charlie}
		\STATE\label{algline: 5}   \textbf{Compute estimate of full gradient}: $g^k\gets \frac{1}{n}\sum_{i=1}^{n}g_i^k$\; \label{beverly}
		\STATE\label{algline: 6}   \textbf{Solve LMO}: $s^{k}\gets \arg\min_{s\in\calC} \langle g^k,s\rangle$\; \label{alex} 
		\STATE\label{algline: 7}   \textbf{Update feasible solution}: $x^{k+1}\gets x^k + \gamma_k (s^{k} - x^k)$. \label{hotel}
		\ENDFOR
		\RETURN $x^{K+1}$
	\end{algorithmic}
\end{algorithm}


Recall that in order to run \cref{alg: TUFW in general finite sum} we need to specify the step-sizes $\{\gamma_k\}_k$ and the {\bf Rule} to construct the sets $\calB_k$ of indices for Taylor-point updating in \cref{fanette}.  Our first rule is designed 
for $\calB_k$ to be comprised of $\beta_k := n /\sqrt{k}$ independently drawn samples from $[n]$ without replacement, for all $k \ge 1$.   Since $\beta_k$ is not in general an integer, then rather than ensuring $|\calB_k| = \beta_k$, we will instead ensure that $\mathbb{E}|\calB_k| = \beta_k$ by proceeding as follows.  



\begin{definition}\label{rule 1} $\rone$.  Define $\beta_k := n /\sqrt{k}$ and $p_k := \beta_k - \lfloor \beta_k \rfloor$.  Sample $\xi_k$ from the Bernoulli distribution $\mathrm{Ber}(p_k)$ and then uniformly sample $\lfloor \beta_k \rfloor + \xi_k$ samples from $[n]$ without replacement.  Then define $\calB_k$ to be the set of these index samples.\end{definition}

Note that by design of $\rone$ it follows that $\mathbb{E}_{\xi_k} |\calB_k| = \beta_k$.  We call this rule ``$\rone$'' for ``Stochastic Batch-size Decreasing at the rate $\sqrt{k}$,'' and we emphasize that the Taylor points are updated less often as $k$ grows, which is in contrast to many other stochastic Frank-Wolfe methods that compute exact individual gradients more frequently as $k$ grows, see \cite{hazan2016variance,yurtsever2019conditional}. 


Let $D$ denote the diameter of $\calC$ under the norm of the variable space, namely
$$
D:= \max_{u,v\in\calC} \| u-v\| \ .
$$


In the rest of the paper, we will use $x^\star$ to denote an optimal solution of the $\erm$ problem, and let $\eps_k := F(x^k) - F(x^\star)$. 


We begin with the following straightforward properties of smooth functions.
\begin{proposition}\label{prop: general basic ineq}
	Under \cref{assump: ERM} for $\erm$,  for any $x$, $y\in\calC$ and $i$, 
	\begin{align}
		| f_i(y) -  f_i(x) - \langle\nabla f_i(x),  y- x\rangle |\le  L\|x-y\|^2 /2 \ , \text{ and } \label{eq: fact: general basic ineq 1} \\
		\| \nabla f_i(y) - \nabla f_i(x) - \langle\nabla^2 f_i(x),  y- x\rangle \|_*\le  \hat{L}\|x-y\|^2 /2 \ . \label{eq: fact: general basic ineq 2}
	\end{align}
\end{proposition}


For any $k \ge 0$ and $i\in [n]$, we will be interested in the most recent iteration (up through $k$) at which Taylor point $b_i$ was updated.  This is defined as:
\begin{equation}\label{def: tau}
	\tau^k_i := \max\{t: t\le k  \text{ and } i \in \calB_t\} \ ,
\end{equation}
which means that in the first $k$ iterations, $\tau^k_i$ is the latest iteration in which the Taylor point $b_i$ was updated. In \cref{alg: TUFW in general finite sum}, the relationship between $\tau^k_i$ and $\tau^{k-1}_i$ is then:
\begin{equation}\label{eq: tauk relationship}
	\tau^{k}_i = \left\{
	\begin{array}{ll}
		k & \text{ if } \  i\in\calB_k \\
		\tau^{k-1}_i & \text{ if } \ i\notin\calB_k \ . 
	\end{array}
	\right.
\end{equation}

