proof.raw_tex:
\begin{lemma}\label{lm: general 3rd term upper bound}
		Under \cref{assump: ERM} for the problem $\erm$, for any $u,v \in\calC$,
		\begin{equation}\label{eq: lm: general 3rd term upper bound}
			\left(
			\nabla F(x^k)   - g^k
			\right)^\top (u - v) \le \frac{\hat{L}D^3}{2n}\sum_{i=1}^{n}\Big( \sum_{j = \tau^k_i}^{k-1}  \gamma_j \Big)^2
		\end{equation}
		holds for iteration $k$ of Algorithm \ref{alg: TUFW in general finite sum} for all $k \ge 1$.
	\end{lemma}

\begin{proof}[Proof of \cref{lm: general 3rd term upper bound}]
		First of all, $\left(
		\nabla F(x^k)   - g^k
		\right)^\top (u - v)$ can be rewritten as
		\begin{small}
			\begin{equation}\label{ineq: general etimate gradient 0}
				\frac{1}{n}\sum_{i=1}^{n}\left(\nabla f_{i}\big(x^k \big) -   \nabla f_{i}\big( x^{\tau^{k}_i}\big) -  \nabla^2 f_{i} \big( x^{\tau^{k}_i}\big)\big(x^k  - x^{\tau^{k}_i} \big)    \right)^\top (u - v),
			\end{equation}	
		\end{small}which, since $\|u-v\| \le D$, is smaller than or equal to 
		\begin{small}\begin{equation}\label{ineq: general etimate gradient 1}
			\frac{D}{n}\sum_{i=1}^{n}\left\| \nabla f_{i}\big(x^k \big) -   \nabla f_{i}\big( x^{\tau^{k}_i}\big) -  \nabla^2 f_{i} \big( x^{\tau^{k}_i}\big)\big(x^k  - x^{\tau^{k}_i} \big)    \right\|_* \le    \frac{\hat{L}D}{2n}\sum_{i=1}^{n}\big\|x^k  - x^{\tau^{k}_i}\big\|^2,
		\end{equation}\end{small}where the inequality is due to \cref{eq: fact: general basic ineq 2} in \cref{prop: general basic ineq}.
		Additionally, we have 
		\begin{small}\begin{equation*}
			\|x^k  - x^{\tau^{k}_i}
			\|^2 \le  \bigg( \sum_{j = \tau^k_i}^{k-1} \| x^{j+1} -  x^{j}\| \bigg)^2\le  \bigg( \sum_{j = \tau^k_i}^{k-1}  \gamma_j D \bigg)^2 \  ,
		\end{equation*}\end{small}and substituting this last bound into \cref{ineq: general etimate gradient 1} yields \cref{eq: lm: general 3rd term upper bound}.
	\end{proof}

\begin{lemma}\label{lm: general convergence rate convex}
		Under \cref{assump: ERM} for problem $\erm$, suppose that $F$ is conevx, and let the step-sizes be given by $\gamma_k=2/(k+2)$ for all $k \ge 0$. Then for all $k \ge 1$ we have
		\begin{equation}\label{eq lm: general convergence rate convex}
			\eps_k  \le  \frac{2L D^2}{k+1}
			+  \frac{2}{k(k+1)}\sum_{t=1}^{k} t \left(
			\nabla F(x^{t-1})   - g^{t-1}
			\right)^\top (s^{t-1} - x^\star) \ .
		\end{equation}
	\end{lemma}

\begin{proof}[Proof of \cref{lm: general convergence rate convex}]
		Utilizing  \cref{prop: general basic ineq} we have
		\begin{small}\begin{equation}\label{eq lm general convergence rate convex 0}
				\begin{aligned}
					F(x^{k+1})\leq ~ & F(x^k)+\gamma_{k}\langle\nabla F(x^k),s^{k}- x^k \rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-g^k, s^{k}-x^k\rangle +\gamma_{k}\langle{g^k}, s^{k}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					\leq ~ & F(x^{k})+\gamma_{k}\langle\nabla F(x^{k})-{g^k}, s^{k}-x^k\rangle + \gamma_{k}\langle{g^k}, {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}\langle \nabla F(x^{k}), {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2}\\
					\le ~& F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}(F(x^\star) - F(x^k))+ \gamma_{k}^{2} {L D^2}/{2} \ , 
				\end{aligned}
		\end{equation}\end{small}where the second inequality uses $s^{k} \in \arg\min_{s\in\calC} (g^k)^\top s$ from \cref{alex} of the algorithm, and the third inequality uses the gradient inequality applied to $F$.  Subtracting $F^\star$ from both sides of the above inequality chain, we arrive at:
		\begin{small}\begin{equation}\label{eq lm general convergence rate convex 1}
				\begin{aligned}
					\eps_{k+1}& \le (1-\gamma_k)\eps_k + \gamma_k \big(
					\nabla F(x^k)   - g^k
					\big)^\top (s^{k} - x^\star) +  {\gamma_k^2 L D^2}/{2} \ .
			\end{aligned}
		\end{equation}\end{small}Multiplying both side by $(k+1)(k+2)$ and telescoping the inequalities yields:
		\begin{small}\begin{equation}
				\begin{aligned}
					(k+1)(k+2)\eps_{k+1}  &\le  2(k+1)L D^2
					+  \sum_{t=0}^{k}2(t+1) (
					\nabla F(x^t)   - g^t
					)^\top (s^{t} - x^\star) \ ,
			\end{aligned}
		\end{equation}\end{small}which yields \cref{eq lm: general convergence rate convex} after rearranging and re-indexing the counter $t$.
	\end{proof}

\begin{lemma}\label{lm: convex EZ} Let the series $\{d_{ij}\}_{i\in[n],j\in\mathbb{N}}$ be given, and suppose that there exist $M_{1}$ and $M_{\infty}$ for which $\sup_{j} \sum_{i=1}^n d_{ij} \le M_{1}$ and  $\sup_{i,j} d_{ij}\le M_{\infty}$.  
		Let $\tau_i^k$ be defined in \cref{def: tau}, in which $\calB_t$ is constructed using $\rone$ in \cref{rule 1}. Let $\gamma_k$ be ${2}/(k+2)$ for all $k \ge 0$.  Then it holds that
		\begin{equation}\label{eq: lm: convex EZ}
			\mathbb{E}\bigg[\sum_{i=1}^{n}\Big( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \Big)\bigg] \le
			\frac{6 M_1}{\sqrt{k+2}} \ \ \text{ and }   \ \
			\mathbb{E} \bigg[\sum_{i=1}^{n}\Big( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \Big)^2 \bigg]\le  \frac{134M_1M_\infty}{k+2} \ .
		\end{equation}
	\end{lemma}

\begin{proposition}\label{lm: rho}
		For integers $v$ and $k$ satisfying $1\le  v \le k$ it holds that:
		\begin{equation}\label{eq: fact 2}
			\sum_{i=1}^{v}\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) <
			(\sqrt{v+1})\exp(2\sqrt{v+1} - 2\sqrt{k+1})  \   .
		\end{equation}
	\end{proposition}

\begin{proof}[Proof of \cref{lm: rho}]
		For convenience let us define $\rho_j := 1-\tfrac{1}{\sqrt{j}}$ for $j \ge 1$, and define the function $h(x):= \exp(2 \sqrt{x} - 2 \sqrt{k+1}) $ for $x \ge 0$.  We will first prove the following inequality:
		\begin{small}\begin{equation}\label{lulu}
			\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) \le h(i) \ \ \ \mathrm{for~all~} i \in [k] \ . 
		\end{equation}\end{small}For $i=1$ the left side above is $0$ (because $\rho_1 = 0$ and hence $\prod_{j=1}^{k}\rho_j = 0$), and the right side is $h(1) >0$, so \cref{lulu} is true for $i=1$. For $i\ge2$ we have:
		\begin{small}\begin{equation*}\begin{aligned}
				\prod_{j=i}^{k}\rho_j  &= \exp\left({\sum_{j=i}^{k}\ln(1-\tfrac{1}{\sqrt{j}})}\right) \le \exp\left( -\sum_{j=i}^{k}\tfrac{1}{\sqrt{j}}\right)  \\  
				&\le \exp\Big( -\int_i^{k+1} x^{-\tfrac{1}{2}} dx\Big) =\exp(2\sqrt{i} - 2\sqrt{k+1}) = h(i) \ , \end{aligned} 
		\end{equation*}\end{small}where the first inequality follows from the fact that $\log(1-x)\le -x$ for any $0\le x <1$, and the second inequality is an integral bound. This establishes \cref{lulu}, whereby we have
		\begin{small}$$ \begin{aligned}
				\sum_{i=1}^{v}   \prod_{j=i}^{k}\rho_j  &\le  \sum_{i=1}^{v} h(i) \le \int_{1}^{v+1}h(x)~dx = \left. (\sqrt{x}-\tfrac{1}{2})\exp(2\sqrt{x} - 2\sqrt{k+1}) \right|_1^{v+1} \\ 
				  &= (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) - (\tfrac{1}{2})\exp(2 - 2\sqrt{k+1}) \\\
				&< (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) \ ,
		\end{aligned}$$\end{small}where the second inequality is an integral bound using the fact that $h(x)$ is an increasing function. \end{proof}

\begin{lemma}\label{lm: simple ineq}
		For any $k\in\mathbb{N}$ the following inequality holds:
		\begin{equation}\label{ineq: lm: simple ineq} 
			\sqrt{\lfloor k/2 \rfloor + 1} \exp(2\sqrt{\lfloor k/2\rfloor + 1} - 2\sqrt{k+1}) \le \min\{{3}(k+2)^{-\frac{1}{2}},{10}(k+2)^{-1}\}. 
		\end{equation}
	\end{lemma}

\begin{proof}[Proof of \cref{lm: simple ineq}]
		Since $h(x):=\sqrt{x}$ is a concave function on $\mathbb{R}_+$, we have $h(k+2) \le h(k+1) + h'(k+1)$, which yields $\sqrt{k+1}\ge \sqrt{k+2} - \frac{1}{2\sqrt{k+1}} \ge \sqrt{k+2} - \sqrt{2}/4 $ when $k \ge 1$.
		Furthermore $\sqrt{\lfloor k/2 \rfloor + 1} \le \frac{\sqrt{2}}{2} \sqrt{k+2}$, and therefore 
		\begin{small}\begin{equation*}
			\sqrt{\lfloor k/2 \rfloor + 1} \exp(2\sqrt{\lfloor k/2\rfloor + 1} - 2\sqrt{k+1}) \le  \frac{\sqrt{2}e^{\frac{\sqrt{2}}{2}}}{2}(k+2)^{\frac{1}{2}}  \exp(-(2-\sqrt{2})(k+2)^{\frac{1}{2}}) \ .
		\end{equation*}\end{small}Next note that the function $h(x):=e^{-x} x^t$ on the domain $x \in (0,\infty)$ for $t > 0$ attains its maximal value at $x = t$. In particular for $t=2$ and $t=3$, respectively, we conclude that $e^{-x} \le 4e^{-2}x^{-2}$ and $e^{-x} \le 27e^{-3}x^{-3}$ (respectively), and thus  $\exp(-(2-\sqrt{2})(k+2)^{\frac{1}{2}}) \le 4 e^{-2}(2-\sqrt{2})^{-2}(k+2)^{-1}$
		and $\exp(-(2-\sqrt{2})(k+2)^{\frac{1}{2}}) \le 27 e^{-3}(2-\sqrt{2})^{-3}(k+2)^{-3/2}$ (respectively).
		Therefore, the left-hand side of \cref{ineq: lm: simple ineq} is bounded by 
		$2\sqrt{2}e^{\frac{\sqrt{2}}{2}-2} (2-\sqrt{2})^{-2} (k+2)^{-\frac{1}{2}}$ and 
		$\frac{27}{2}\sqrt{2}e^{\frac{\sqrt{2}}{2}-3} (2-\sqrt{2})^{-3} (k+2)^{-1}$, respectively, which is less than $3(k+2)^{-\frac{1}{2}}$ and $10(k+2)^{-1}$, respectively.
	\end{proof}

\begin{proof}[Proof of \cref{lm: convex EZ}]

		First of all, let us define $G_k^i := \left( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \right)$ and $Z_k^i :=\left( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \right)^2$ for $i \in [n]$, and also $G_k :=\sum_{i=1}^n G_k^i$ and $Z_k :=\sum_{i=1}^n Z_k^i$. Notice in $G_k^i$ and $Z_k^i$ that the randomness lies only in $\tau_i^k$, which in turn depends on the update sets $\calB_0, \calB_1,\dots,\calB_k$. 

		We first analyze $G_k^i$ and $G_k$.  We note that $G_k^i = 0$ when $i \in \calB_k$, which happens with probability $\beta_k/n$.  Because of the relationship between $\{\tau^k_i\}$ and $\{\tau^{k-1}_i\}$ in \cref{eq: tauk relationship}, we further note that with probability $1-\beta_k/n$ that $i \notin \calB_k$ in which case it follows that $G_k^i = G_{k-1}^i + \gamma_{k-1}d_{i,k-1}$.  Defining $\rho_k := 1 - \frac{1}{\sqrt{k}} = 1 - \beta_k/n $, we have 
		\begin{small}\begin{equation}\label{ncl}
			\mathbb{E}[ G_k ] = \sum_{i=1}^n \mathbb{E} [G_k^i ]= \rho_k \sum_{i=1}^n \mathbb{E} [G_{k-1}^i +
			\gamma_{k-1} d_{i,k-1}] \le \rho_k\left( \mathbb{E} [G_{k-1} ]+
			\gamma_{k-1} M_1 \right) \ ,
		\end{equation}\end{small}where the inequality uses $\sup_{j} \sum_{i=1}^n d_{ij} \le M_{1}$. Recurrently applying \cref{ncl} yields:
		\begin{small}\begin{equation}\label{ineq: recurrent G_k 2}
			 \mathbb{E}[ G_k ] \le \rho_k( \mathbb{E}[ G_{k-1} ]+
			\gamma_{k-1}  M_1 ) \le\cdots\le \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \gamma_{i-1} M_1 + \Big(\prod_{j=1}^{k} \rho_j\Big)\mathbb{E}[ G_0] \ .
		\end{equation}\end{small}Noting that $G_0 = 0$ (since all Taylor points are set to $x^0$ in \cref{bettina} of \cref{alg: TUFW in general finite sum}) and using $\gamma_{i-1} = \frac{2}{i+1}$ it follows that:
		\begin{small}\begin{equation}\label{ineq: recurrent G_k 3}
			\begin{aligned}
				\mathbb{E} [G_k] &\le \sum_{i=1}^{\lfloor {k}/{2}\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{i+1}
				+
				\sum_{i=\lfloor {k}/{2}\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{i+1}\\
				& \le \sum_{i=2}^{\lfloor {k}/{2}\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{3}
				+
				\sum_{i=\lfloor {k}/{2}\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{\lfloor {k}/{2}\rfloor+2} \ ,
			\end{aligned}
		\end{equation}\end{small}where the second inequality uses the fact that $\rho_1 = 0$ and hence $\prod_{j=1}^{k}\rho_j = 0$.
		By \cref{lm: rho} we have:
		\begin{small}\begin{equation}\label{ineq: G_k recurrent sumpro 1}
			\sum_{i=1}^{\lfloor {k}/{2}\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)  \frac{2M_1}{3}
			\le
			\sqrt{\lfloor {k}/{2}
				\rfloor + 1} \exp\Big(2 \sqrt{ \lfloor {k}/{2} \rfloor + 1} - 2\sqrt{k+1}\Big)  \frac{2M_1}{3} \le \frac{2 M_1}{\sqrt{k+2}} \ ,
		\end{equation}\end{small}where the second inequality above uses \cref{lm: simple ineq}.
		Similarly for the second term in the rightmost side of \cref{ineq: recurrent G_k 3} we have:
		\begin{small}\begin{equation}\label{ineq: G_k recurrent sumpro 2}
			\sum_{i=\lfloor k/2 \rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{\lfloor k/2\rfloor+2} \le   \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{\lfloor k/2\rfloor+2} \le \frac{\sqrt{k+1} \cdot  2M_1}{\lfloor k/2\rfloor+2} \le \frac{4M_1}{\sqrt{k+2}} \ , 
		\end{equation}\end{small}where the second inequality uses \cref{lm: rho}.
		Substituting \cref{ineq: G_k recurrent sumpro 1} and \cref{ineq: G_k recurrent sumpro 2} back into \cref{ineq: recurrent G_k 3} yields the first part of \cref{eq: lm: convex EZ}, namely:
		\begin{equation}\label{ineq: convex EG_k final}
			\mathbb{E} [G_k] \le {6 M_1}/{\sqrt{k+2}} \ .
		\end{equation}

		We employ a similar proof approach to establish the second part of \cref{eq: lm: convex EZ}. We note that $Z_k^i = 0$ when $i \in \calB_k$, which happens with probability $\beta_k/n$.  Because of the relationship between $\{\tau^k_i\}$ and $\{\tau^{k-1}_i\}$ in \cref{eq: tauk relationship}, we further note that with probability $1-\beta_k/n$ that $i \notin \calB_k$ in which case we have
		\begin{small}\begin{equation*}
			\begin{aligned} 
				Z_k^i &= (G_{k-1}^i + \gamma_{k-1}d_{i,k-1})^2 = Z_{k-1}^i + 2 G_{k-1}^i\gamma_{k-1}d_{i,k-1} + (\gamma_{k-1}d_{i,k-1})^2 \\ &\le Z_{k-1}^i + 2 M_\infty \gamma_{k-1}G_{k-1}^i + \gamma_{k-1}^2 M_\infty d_{i,k-1} \ . 
			\end{aligned}\end{equation*}\end{small}Therefore
		\begin{small}\begin{equation}\begin{aligned}\label{nclz}
				\mathbb{E}[ Z_k ] = &\sum_{i=1}^n \mathbb{E} [Z_k^i ] \le \rho_k \sum_{i=1}^n \mathbb{E} [Z_{k-1}^i + 2 M_\infty \gamma_{k-1}G_{k-1}^i + \gamma_{k-1}^2 M_\infty d_{i,k-1}] \\ 
				&\le \rho_k \left( \mathbb{E} [Z_{k-1}] + 2   M_\infty \gamma_{k-1}\mathbb{E}[G_{k-1}] +   \gamma_{k-1}^2 M_\infty M_1 \right) \\
				&\le \rho_k \left(\mathbb{E} [Z_{k-1}] + \frac{24M_\infty M_1}{(k+1)\sqrt{k+1}}   +  \frac{4M_\infty M_1}{(k+1)^2} \right) \le \rho_k \left(\mathbb{E} [Z_{k-1}] + \frac{28M_\infty M_1}{(k+1)\sqrt{k+1}}  \right)    \ ,
		\end{aligned}\end{equation} \end{small}where the second inequality uses $\sup_{j} \sum_{i=1}^n d_{ij} \le M_{1}$, and the third inequality uses \cref{ineq: convex EG_k final}. Recurrently applying \cref{nclz} yields:
		\begin{small}\begin{equation}\label{ineq: recurrent Z_k 4}
			\mathbb{E} [Z_k]  \le \rho_k\bigg( \mathbb{E} [Z_{k-1} ]+
			\frac{28M_1M_\infty}{(k+1)^{3/2}}\bigg) \le \cdots\le \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(i+1)^{3/2}}  \ .
		\end{equation}\end{small}Therefore
		\begin{small}\begin{equation}\label{ineq: recurrent Z_k 5}
			\begin{aligned}
				\mathbb{E} [Z_k]  & \le  \sum_{i=1}^{\lfloor k/2\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(i+1)^{3/2}}
				+
				\sum_{i=\lfloor k/2\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(i+1)^{3/2}}\\
				& \le \sum_{i=1}^{\lfloor k/2\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{3\sqrt{3}}
				+
				\sum_{i=\lfloor k/2\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{28M_1M_\infty}{(\lfloor k/2\rfloor +2)^{3/2}} \ .
			\end{aligned}
		\end{equation}\end{small}By \cref{lm: rho} we have 
			\begin{small}\begin{equation}\label{ineq: Z_k recurrent sumpro 1}
			\begin{aligned}
				\sum_{i=1}^{\lfloor k/2\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{3\sqrt{3}}  &\le \sqrt{\lfloor k/2
					\rfloor + 1} \exp\big(2 \sqrt{ \lfloor k/2 \rfloor + 1} - 2\sqrt{k+1}\big) \cdot \frac{28M_1M_\infty}{(3\sqrt{3})} \\ 
				&\le \frac{{54M_1M_\infty}}{k+2} \ , 
		\end{aligned}\end{equation}\end{small}where the second inequality above uses \cref{lm: simple ineq}. 
		Similarly for the second term in the rightmost side of \cref{ineq: recurrent Z_k 5} we have:
			\begin{small}\begin{equation}
			\begin{aligned}\label{ineq: Z_k recurrent sumpro 2}
				\sum_{i=\lfloor k/2 \rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(\lfloor k/2\rfloor +2)^{3/2}} &\le   \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{28M_1M_\infty}{(\lfloor k/2\rfloor +2)^{3/2}} \\ 
				&\le \sqrt{k+1} \cdot \frac{28M_1M_\infty}{(\lfloor k/2\rfloor +2)^{3/2}} \le \frac{80M_1M_\infty}{k+2} \ ,
			\end{aligned}
		\end{equation}\end{small}where the second inequality uses \cref{lm: rho}.
		Substituting \cref{ineq: Z_k recurrent sumpro 1} and \cref{ineq: Z_k recurrent sumpro 2} back into \cref{ineq: recurrent Z_k 5} yields the second part of \cref{eq: lm: convex EZ}, namely:
		\begin{small}
			\begin{equation}\label{ineq: convex EZ_k final}
				\mathbb{E} [Z_k] \le  \frac{134M_1M_\infty}{k+2} \ .
			\end{equation}
		\end{small}\end{proof}

\begin{proof}[Proof of \cref{thm: general convergence rate convex}]
		From \cref{lm: general convergence rate convex} it holds that:
		\begin{small}
			\begin{equation}
				\eps_k  \le  \frac{2L D^2}{k+1}
				+  \frac{2}{k(k+1)}\sum_{t=1}^{k} t \left(
				\nabla F(x^{t-1})   - g^{t-1}
				\right)^\top (s^{t-1} - x^\star) \ ,
			\end{equation}
		\end{small}and from \cref{lm: general 3rd term upper bound} it follows that:
		\begin{small}
			\begin{equation*}
				\eps_k \le  \frac{2L D^2}{k+1}
				+  \frac{\hat{L}D^3}{nk(k+1)}\sum_{t=1}^{k}t\sum_{i=1}^{n}\Big( \sum_{j = \tau^{t-1}_i}^{t-2}  \gamma_j \Big)^2 \ .
			\end{equation*}
		\end{small}Taking expectations on both sides then yields
		\begin{small}
			\begin{equation}\label{ineq: convex thm 1 general}
				\mathbb{E} [\eps_k]  \le  \frac{2L D^2}{k+1}
				+  \frac{\hat{L}D^3}{nk(k+1)}\sum_{t=1}^{k}t~\mathbb{E}\Big[
				\sum_{i=1}^{n}\Big(  \sum_{j = \tau^{t-1}_i}^{t-2}  \gamma_j \Big)^2
				\Big] \ .
			\end{equation}
		\end{small}Now define $d_{ij} := 1$ and $M_1 := n$ and $M_\infty := 1$.  Then since $\sup_{j}   \sum_{i=1}^{n} d_{ij} = M_1$  and  $\sup_{i,j} d_{ij}$ is equal to $M_\infty$, we can apply \cref{lm: convex EZ} to \cref{ineq: convex thm 1 general}  and obtain
		\begin{small}
			\begin{equation}\label{ineq: convex thm 2 general}
				\mathbb{E} [\eps_k]   \le  \frac{2L D^2}{k+1}
				+  \frac{\hat{L}D^3}{nk(k+1)}\sum_{t=1}^{k}t~\frac{134 n}{t+1} \le \frac{2L D^2}{k+1}
				+  \frac{134 \hat{L}D^3}{k+1} \ , 
			\end{equation}
		\end{small}which proves \cref{eq of thm: general convergence rate convex}.
	\end{proof}

