\begin{proposition}\label{lm: rho}
		For integers $v$ and $k$ satisfying $1\le  v \le k$ it holds that:
		\begin{equation}\label{eq: fact 2}
			\sum_{i=1}^{v}\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) <
			(\sqrt{v+1})\exp(2\sqrt{v+1} - 2\sqrt{k+1})  \   .
		\end{equation}
	\end{proposition}

\begin{proof}[Proof of \cref{lm: rho}]
		For convenience let us define $\rho_j := 1-\tfrac{1}{\sqrt{j}}$ for $j \ge 1$, and define the function $h(x):= \exp(2 \sqrt{x} - 2 \sqrt{k+1}) $ for $x \ge 0$.  We will first prove the following inequality:
		\begin{small}\begin{equation}\label{lulu}
			\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) \le h(i) \ \ \ \mathrm{for~all~} i \in [k] \ . 
		\end{equation}\end{small}For $i=1$ the left side above is $0$ (because $\rho_1 = 0$ and hence $\prod_{j=1}^{k}\rho_j = 0$), and the right side is $h(1) >0$, so \cref{lulu} is true for $i=1$. For $i\ge2$ we have:
		\begin{small}\begin{equation*}\begin{aligned}
				\prod_{j=i}^{k}\rho_j  &= \exp\left({\sum_{j=i}^{k}\ln(1-\tfrac{1}{\sqrt{j}})}\right) \le \exp\left( -\sum_{j=i}^{k}\tfrac{1}{\sqrt{j}}\right)  \\  
				&\le \exp\Big( -\int_i^{k+1} x^{-\tfrac{1}{2}} dx\Big) =\exp(2\sqrt{i} - 2\sqrt{k+1}) = h(i) \ , \end{aligned} 
		\end{equation*}\end{small}where the first inequality follows from the fact that $\log(1-x)\le -x$ for any $0\le x <1$, and the second inequality is an integral bound. This establishes \cref{lulu}, whereby we have
		\begin{small}$$ \begin{aligned}
				\sum_{i=1}^{v}   \prod_{j=i}^{k}\rho_j  &\le  \sum_{i=1}^{v} h(i) \le \int_{1}^{v+1}h(x)~dx = \left. (\sqrt{x}-\tfrac{1}{2})\exp(2\sqrt{x} - 2\sqrt{k+1}) \right|_1^{v+1} \\ 
				  &= (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) - (\tfrac{1}{2})\exp(2 - 2\sqrt{k+1}) \\\
				&< (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) \ ,
		\end{aligned}$$\end{small}where the second inequality is an integral bound using the fact that $h(x)$ is an increasing function. \end{proof}

For convenience let us define $\rho_j := 1-\tfrac{1}{\sqrt{j}}$ for $j \ge 1$, and define the function $h(x):= \exp(2 \sqrt{x} - 2 \sqrt{k+1}) $ for $x \ge 0$.  We will first prove the following inequality:
\begin{small}\begin{equation}\label{lulu}
	\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) \le h(i) \ \ \ \mathrm{for~all~} i \in [k] \ . 
\end{equation}\end{small}For $i=1$ the left side above is $0$ (because $\rho_1 = 0$ and hence $\prod_{j=1}^{k}\rho_j = 0$), and the right side is $h(1) >0$, so \cref{lulu} is true for $i=1$. For $i\ge2$ we have:
\begin{small}\begin{equation*}\begin{aligned}
		\prod_{j=i}^{k}\rho_j  &= \exp\left({\sum_{j=i}^{k}\ln(1-\tfrac{1}{\sqrt{j}})}\right) \le \exp\left( -\sum_{j=i}^{k}\tfrac{1}{\sqrt{j}}\right)  \\  
		&\le \exp\Big( -\int_i^{k+1} x^{-\tfrac{1}{2}} dx\Big) =\exp(2\sqrt{i} - 2\sqrt{k+1}) = h(i) \ , \end{aligned} 
\end{equation*}\end{small}where the first inequality follows from the fact that $\log(1-x)\le -x$ for any $0\le x <1$, and the second inequality is an integral bound. This establishes \cref{lulu}, whereby we have

\begin{small}$$ \begin{aligned}
		\sum_{i=1}^{v}   \prod_{j=i}^{k}\rho_j  &\le  \sum_{i=1}^{v} h(i) \le \int_{1}^{v+1}h(x)~dx = \left. (\sqrt{x}-\tfrac{1}{2})\exp(2\sqrt{x} - 2\sqrt{k+1}) \right|_1^{v+1} \\ 
		  &= (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) - (\tfrac{1}{2})\exp(2 - 2\sqrt{k+1}) \\\
		&< (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) \ ,
\end{aligned}$$\end{small}where the second inequality is an integral bound using the fact that $h(x)$ is an increasing function. \end{proof}

\begin{lemma}\label{lm: simple ineq}
		For any $k\in\mathbb{N}$ the following inequality holds:
		\begin{equation}\label{ineq: lm: simple ineq} 
			\sqrt{\lfloor k/2 \rfloor + 1} \exp(2\sqrt{\lfloor k/2\rfloor + 1} - 2\sqrt{k+1}) \le \min\{{3}(k+2)^{-\frac{1}{2}},{10}(k+2)^{-1}\}. 
		\end{equation}
	\end{lemma}

\begin{proof}[Proof of \cref{lm: convex EZ}]

		First of all, let us define $G_k^i := \left( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \right)$ and $Z_k^i :=\left( \sum_{j = \tau^k_i}^{k-1}  \gamma_j d_{ij} \right)^2$ for $i \in [n]$, and also $G_k :=\sum_{i=1}^n G_k^i$ and $Z_k :=\sum_{i=1}^n Z_k^i$. Notice in $G_k^i$ and $Z_k^i$ that the randomness lies only in $\tau_i^k$, which in turn depends on the update sets $\calB_0, \calB_1,\dots,\calB_k$. 

		We first analyze $G_k^i$ and $G_k$.  We note that $G_k^i = 0$ when $i \in \calB_k$, which happens with probability $\beta_k/n$.  Because of the relationship between $\{\tau^k_i\}$ and $\{\tau^{k-1}_i\}$ in \cref{eq: tauk relationship}, we further note that with probability $1-\beta_k/n$ that $i \notin \calB_k$ in which case it follows that $G_k^i = G_{k-1}^i + \gamma_{k-1}d_{i,k-1}$.  Defining $\rho_k := 1 - \frac{1}{\sqrt{k}} = 1 - \beta_k/n $, we have 
		\begin{small}\begin{equation}\label{ncl}
			\mathbb{E}[ G_k ] = \sum_{i=1}^n \mathbb{E} [G_k^i ]= \rho_k \sum_{i=1}^n \mathbb{E} [G_{k-1}^i +
			\gamma_{k-1} d_{i,k-1}] \le \rho_k\left( \mathbb{E} [G_{k-1} ]+
			\gamma_{k-1} M_1 \right) \ ,
		\end{equation}\end{small}where the inequality uses $\sup_{j} \sum_{i=1}^n d_{ij} \le M_{1}$. Recurrently applying \cref{ncl} yields:
		\begin{small}\begin{equation}\label{ineq: recurrent G_k 2}
			 \mathbb{E}[ G_k ] \le \rho_k( \mathbb{E}[ G_{k-1} ]+
			\gamma_{k-1}  M_1 ) \le\cdots\le \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \gamma_{i-1} M_1 + \Big(\prod_{j=1}^{k} \rho_j\Big)\mathbb{E}[ G_0] \ .
		\end{equation}\end{small}Noting that $G_0 = 0$ (since all Taylor points are set to $x^0$ in \cref{bettina} of \cref{alg: TUFW in general finite sum}) and using $\gamma_{i-1} = \frac{2}{i+1}$ it follows that:
		\begin{small}\begin{equation}\label{ineq: recurrent G_k 3}
			\begin{aligned}
				\mathbb{E} [G_k] &\le \sum_{i=1}^{\lfloor {k}/{2}\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{i+1}
				+
				\sum_{i=\lfloor {k}/{2}\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{i+1}\\
				& \le \sum_{i=2}^{\lfloor {k}/{2}\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{3}
				+
				\sum_{i=\lfloor {k}/{2}\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{\lfloor {k}/{2}\rfloor+2} \ ,
			\end{aligned}
		\end{equation}\end{small}where the second inequality uses the fact that $\rho_1 = 0$ and hence $\prod_{j=1}^{k}\rho_j = 0$.
		By \cref{lm: rho} we have:
		\begin{small}\begin{equation}\label{ineq: G_k recurrent sumpro 1}
			\sum_{i=1}^{\lfloor {k}/{2}\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)  \frac{2M_1}{3}
			\le
			\sqrt{\lfloor {k}/{2}
				\rfloor + 1} \exp\Big(2 \sqrt{ \lfloor {k}/{2} \rfloor + 1} - 2\sqrt{k+1}\Big)  \frac{2M_1}{3} \le \frac{2 M_1}{\sqrt{k+2}} \ ,
		\end{equation}\end{small}where the second inequality above uses \cref{lm: simple ineq}.
		Similarly for the second term in the rightmost side of \cref{ineq: recurrent G_k 3} we have:
		\begin{small}\begin{equation}\label{ineq: G_k recurrent sumpro 2}
			\sum_{i=\lfloor k/2 \rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{\lfloor k/2\rfloor+2} \le   \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{2M_1}{\lfloor k/2\rfloor+2} \le \frac{\sqrt{k+1} \cdot  2M_1}{\lfloor k/2\rfloor+2} \le \frac{4M_1}{\sqrt{k+2}} \ , 
		\end{equation}\end{small}where the second inequality uses \cref{lm: rho}.
		Substituting \cref{ineq: G_k recurrent sumpro 1} and \cref{ineq: G_k recurrent sumpro 2} back into \cref{ineq: recurrent G_k 3} yields the first part of \cref{eq: lm: convex EZ}, namely:
		\begin{equation}\label{ineq: convex EG_k final}
			\mathbb{E} [G_k] \le {6 M_1}/{\sqrt{k+2}} \ .
		\end{equation}

		We employ a similar proof approach to establish the second part of \cref{eq: lm: convex EZ}. We note that $Z_k^i = 0$ when $i \in \calB_k$, which happens with probability $\beta_k/n$.  Because of the relationship between $\{\tau^k_i\}$ and $\{\tau^{k-1}_i\}$ in \cref{eq: tauk relationship}, we further note that with probability $1-\beta_k/n$ that $i \notin \calB_k$ in which case we have
		\begin{small}\begin{equation*}
			\begin{aligned} 
				Z_k^i &= (G_{k-1}^i + \gamma_{k-1}d_{i,k-1})^2 = Z_{k-1}^i + 2 G_{k-1}^i\gamma_{k-1}d_{i,k-1} + (\gamma_{k-1}d_{i,k-1})^2 \\ &\le Z_{k-1}^i + 2 M_\infty \gamma_{k-1}G_{k-1}^i + \gamma_{k-1}^2 M_\infty d_{i,k-1} \ . 
			\end{aligned}\end{equation*}\end{small}Therefore
		\begin{small}\begin{equation}\begin{aligned}\label{nclz}
				\mathbb{E}[ Z_k ] = &\sum_{i=1}^n \mathbb{E} [Z_k^i ] \le \rho_k \sum_{i=1}^n \mathbb{E} [Z_{k-1}^i + 2 M_\infty \gamma_{k-1}G_{k-1}^i + \gamma_{k-1}^2 M_\infty d_{i,k-1}] \\ 
				&\le \rho_k \left( \mathbb{E} [Z_{k-1}] + 2   M_\infty \gamma_{k-1}\mathbb{E}[G_{k-1}] +   \gamma_{k-1}^2 M_\infty M_1 \right) \\
				&\le \rho_k \left(\mathbb{E} [Z_{k-1}] + \frac{24M_\infty M_1}{(k+1)\sqrt{k+1}}   +  \frac{4M_\infty M_1}{(k+1)^2} \right) \le \rho_k \left(\mathbb{E} [Z_{k-1}] + \frac{28M_\infty M_1}{(k+1)\sqrt{k+1}}  \right)    \ ,
		\end{aligned}\end{equation} \end{small}where the second inequality uses $\sup_{j} \sum_{i=1}^n d_{ij} \le M_{1}$, and the third inequality uses \cref{ineq: convex EG_k final}. Recurrently applying \cref{nclz} yields:
		\begin{small}\begin{equation}\label{ineq: recurrent Z_k 4}
			\mathbb{E} [Z_k]  \le \rho_k\bigg( \mathbb{E} [Z_{k-1} ]+
			\frac{28M_1M_\infty}{(k+1)^{3/2}}\bigg) \le \cdots\le \sum_{i=1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(i+1)^{3/2}}  \ .
		\end{equation}\end{small}Therefore
		\begin{small}\begin{equation}\label{ineq: recurrent Z_k 5}
			\begin{aligned}
				\mathbb{E} [Z_k]  & \le  \sum_{i=1}^{\lfloor k/2\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(i+1)^{3/2}}
				+
				\sum_{i=\lfloor k/2\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{(i+1)^{3/2}}\\
				& \le \sum_{i=1}^{\lfloor k/2\rfloor}\Big(\prod_{j=i}^{k}\rho_j\Big)\frac{28M_1M_\infty}{3\sqrt{3}}
				+
				\sum_{i=\lfloor k/2\rfloor+1}^{k}\Big(\prod_{j=i}^{k}\rho_j\Big) \frac{28M_1M_\infty}{(\lfloor k/2\rfloor +2)^{3/2}} \ .
			\end{aligned}
		\end{equation}\end{small}By \cref{lm: rho} we have 
			\begin{small}\begin{equation}\label{ineq: Z_k recurrent sumpro 1}
