\begin{lemma}\label{lm: general convergence rate convex}
		Under \cref{assump: ERM} for problem $\erm$, suppose that $F$ is conevx, and let the step-sizes be given by $\gamma_k=2/(k+2)$ for all $k \ge 0$. Then for all $k \ge 1$ we have
		\begin{equation}\label{eq lm: general convergence rate convex}
			\eps_k  \le  \frac{2L D^2}{k+1}
			+  \frac{2}{k(k+1)}\sum_{t=1}^{k} t \left(
			\nabla F(x^{t-1})   - g^{t-1}
			\right)^\top (s^{t-1} - x^\star) \ .
		\end{equation}
	\end{lemma}

\begin{proof}[Proof of \cref{lm: general convergence rate convex}]
		Utilizing  \cref{prop: general basic ineq} we have
		\begin{small}\begin{equation}\label{eq lm general convergence rate convex 0}
				\begin{aligned}
					F(x^{k+1})\leq ~ & F(x^k)+\gamma_{k}\langle\nabla F(x^k),s^{k}- x^k \rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-g^k, s^{k}-x^k\rangle +\gamma_{k}\langle{g^k}, s^{k}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					\leq ~ & F(x^{k})+\gamma_{k}\langle\nabla F(x^{k})-{g^k}, s^{k}-x^k\rangle + \gamma_{k}\langle{g^k}, {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2} \\
					= ~ & F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}\langle \nabla F(x^{k}), {x}^{\star}-x^k\rangle+ \gamma_{k}^{2} {L D^2}/{2}\\
					\le ~& F(x^{k})+\gamma_{k}\langle \nabla F(x^{k})-{g^k},s^{k}-{x}^{\star}\rangle +\gamma_{k}(F(x^\star) - F(x^k))+ \gamma_{k}^{2} {L D^2}/{2} \ , 
				\end{aligned}
		\end{equation}\end{small}where the second inequality uses $s^{k} \in \arg\min_{s\in\calC} (g^k)^\top s$ from \cref{alex} of the algorithm, and the third inequality uses the gradient inequality applied to $F$.  Subtracting $F^\star$ from both sides of the above inequality chain, we arrive at:
		\begin{small}\begin{equation}\label{eq lm general convergence rate convex 1}
				\begin{aligned}
					\eps_{k+1}& \le (1-\gamma_k)\eps_k + \gamma_k \big(
					\nabla F(x^k)   - g^k
					\big)^\top (s^{k} - x^\star) +  {\gamma_k^2 L D^2}/{2} \ .
			\end{aligned}
		\end{equation}\end{small}Multiplying both side by $(k+1)(k+2)$ and telescoping the inequalities yields:
		\begin{small}\begin{equation}
				\begin{aligned}
					(k+1)(k+2)\eps_{k+1}  &\le  2(k+1)L D^2
					+  \sum_{t=0}^{k}2(t+1) (
					\nabla F(x^t)   - g^t
					)^\top (s^{t} - x^\star) \ ,
			\end{aligned}
		\end{equation}\end{small}which yields \cref{eq lm: general convergence rate convex} after rearranging and re-indexing the counter $t$.
	\end{proof}

Utilizing  \cref{prop: general basic ineq} we have
\begin{small}\begin{equation}\label{eq lm general convergence rate convex 0}
