\begin{proposition}\label{lm: rho}
		For integers $v$ and $k$ satisfying $1\le  v \le k$ it holds that:
		\begin{equation}\label{eq: fact 2}
			\sum_{i=1}^{v}\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) <
			(\sqrt{v+1})\exp(2\sqrt{v+1} - 2\sqrt{k+1})  \   .
		\end{equation}
	\end{proposition}

\begin{proof}[Proof of \cref{lm: rho}]
		For convenience let us define $\rho_j := 1-\tfrac{1}{\sqrt{j}}$ for $j \ge 1$, and define the function $h(x):= \exp(2 \sqrt{x} - 2 \sqrt{k+1}) $ for $x \ge 0$.  We will first prove the following inequality:
		\begin{small}\begin{equation}\label{lulu}
			\prod_{j=i}^{k}\left(1-\tfrac{1}{\sqrt{j}}\right) \le h(i) \ \ \ \mathrm{for~all~} i \in [k] \ . 
		\end{equation}\end{small}For $i=1$ the left side above is $0$ (because $\rho_1 = 0$ and hence $\prod_{j=1}^{k}\rho_j = 0$), and the right side is $h(1) >0$, so \cref{lulu} is true for $i=1$. For $i\ge2$ we have:
		\begin{small}\begin{equation*}\begin{aligned}
				\prod_{j=i}^{k}\rho_j  &= \exp\left({\sum_{j=i}^{k}\ln(1-\tfrac{1}{\sqrt{j}})}\right) \le \exp\left( -\sum_{j=i}^{k}\tfrac{1}{\sqrt{j}}\right)  \\  
				&\le \exp\Big( -\int_i^{k+1} x^{-\tfrac{1}{2}} dx\Big) =\exp(2\sqrt{i} - 2\sqrt{k+1}) = h(i) \ , \end{aligned} 
		\end{equation*}\end{small}where the first inequality follows from the fact that $\log(1-x)\le -x$ for any $0\le x <1$, and the second inequality is an integral bound. This establishes \cref{lulu}, whereby we have
		\begin{small}$$ \begin{aligned}
				\sum_{i=1}^{v}   \prod_{j=i}^{k}\rho_j  &\le  \sum_{i=1}^{v} h(i) \le \int_{1}^{v+1}h(x)~dx = \left. (\sqrt{x}-\tfrac{1}{2})\exp(2\sqrt{x} - 2\sqrt{k+1}) \right|_1^{v+1} \\ 
				  &= (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) - (\tfrac{1}{2})\exp(2 - 2\sqrt{k+1}) \\\
				&< (\sqrt{v+1}-\tfrac{1}{2})\exp(2\sqrt{v+1} - 2\sqrt{k+1}) \ ,
		\end{aligned}$$\end{small}where the second inequality is an integral bound using the fact that $h(x)$ is an increasing function. \end{proof}

